INSERT INTO services (title, slug, description, imageUrl, active, "order") VALUES
('Fotocopy Hitam Putih', 'fotocopy-hitam-putih', 'Layanan fotocopy hitam putih untuk dokumen akademik, arsip, formulir, dan administrasi. Cocok untuk tugas kuliah, modul, dan dokumen sehari-hari. Tersedia ukuran A4 dan F4, melayani cetak satuan maupun dalam jumlah besar dengan hasil rapi dan jelas.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/c6e26a1be55e4d5c952814b857600bbc.png', 1, 1),
('Fotocopy Warna', 'fotocopy-warna', 'Layanan fotocopy warna untuk dokumen yang membutuhkan tampilan visual, seperti proposal, laporan, dan presentasi. Hasil warna proporsional dan rapi, tersedia ukuran A4 dan F4.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/c6e26a1be55e4d5c952814b857600bbc.png', 1, 2),
('Print Hitam Putih', 'print-hitam-putih', 'Layanan print dokumen hitam putih dari file digital seperti PDF, Word, dan format umum lainnya. File dapat dikirim melalui flashdisk, WhatsApp, atau email. Cocok untuk dokumen akademik dan administrasi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 3),
('Print Warna', 'print-warna', 'Layanan print warna untuk dokumen dengan elemen grafis seperti cover laporan, proposal, poster kecil, dan materi presentasi. Dicetak rapi dan jelas sesuai ukuran kertas yang dibutuhkan.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 4),
('Scan Dokumen', 'scan-dokumen', 'Layanan scan dokumen fisik menjadi file digital format PDF atau JPG. Cocok untuk arsip, pengiriman online, dan penyimpanan dokumen penting.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 5),
('Edit & Perapihan Dokumen', 'edit-perapihan-dokumen', 'Layanan perbaikan dokumen meliputi margin, spasi, ukuran kertas, penomoran halaman, serta penggabungan dan pemisahan file PDF agar siap dicetak atau dikirim.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 6),
('Pengetikan Dokumen', 'pengetikan-dokumen', 'Layanan pengetikan dari tulisan tangan atau file mentah untuk surat, laporan, makalah, dan dokumen administrasi lainnya.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 7),
('Jilid Spiral', 'jilid-spiral', 'Penjilidan spiral plastik atau kawat untuk laporan, modul, dan dokumen kerja. Mudah dibuka-tutup dan cocok untuk penggunaan harian.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 8),
('Jilid Lakban', 'jilid-lakban', 'Penjilidan lakban untuk dokumen tipis hingga sedang. Sederhana, rapi, dan ekonomis untuk tugas atau arsip.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 9),
('Jilid Hardcover', 'jilid-hardcover', 'Penjilidan hardcover untuk skripsi, tesis, disertasi, dan buku. Tampilan kuat dan elegan, cocok untuk dokumen resmi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 10),
('Laminating', 'laminating', 'Layanan laminating dokumen penting seperti KTP, kartu mahasiswa, sertifikat, dan surat berharga agar lebih awet dan tahan lama.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 11),
('Paket Skripsi / Tesis', 'paket-skripsi-tesis', 'Layanan paket lengkap meliputi print dokumen, penjilidan, dan kebutuhan pendukung lainnya. Dirancang agar dokumen siap dikumpulkan tanpa proses terpisah.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 12),
('Burning CD / DVD', 'burning-cd-dvd', 'Layanan pemindahan file ke CD atau DVD untuk keperluan skripsi, laporan, atau arsip digital.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 13),
('Cetak Modul & Buku', 'cetak-modul-buku', 'Layanan cetak modul pembelajaran dan buku dalam jumlah kecil hingga menengah. Cocok untuk dosen, guru, dan pelatihan.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 14),
('Jasa Pembuatan Buku ISBN', 'jasa-pembuatan-buku-isbn', 'Layanan pembuatan ISBN buku dengan sistem menginduk pada penerbit resmi melalui Rizquna. Cocok untuk penulis, dosen, dan guru yang ingin menerbitkan buku secara legal.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 15),
('Cetak Brosur', 'cetak-brosur', 'Layanan cetak brosur untuk promosi, informasi, dan kegiatan organisasi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 16),
('Cetak Pamflet / Flyer', 'cetak-pamflet-flyer', 'Layanan cetak pamflet untuk penyebaran informasi dan promosi sederhana.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 17),
('Cetak Poster', 'cetak-poster-baru', 'Layanan cetak poster ukuran A4 dan A3 untuk pengumuman, presentasi, dan kegiatan visual.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/c9bef1a7ffb548459120a2b52c925ba9.jpg', 1, 18),
('Cetak Banner Kecil', 'cetak-banner-kecil', 'Layanan cetak banner ukuran kecil untuk kebutuhan promosi atau pengumuman.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 19),
('Cetak Stiker', 'cetak-stiker', 'Layanan cetak stiker untuk label produk, kemasan, penanda barang, dan kebutuhan promosi sederhana.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/c9bef1a7ffb548459120a2b52c925ba9.jpg', 1, 20),
('Cetak Label Produk', 'cetak-label-produk', 'Layanan cetak label produk untuk kemasan UMKM seperti makanan dan minuman.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/c9bef1a7ffb548459120a2b52c925ba9.jpg', 1, 21),
('Cetak Kartu Nama', 'cetak-kartu-nama', 'Layanan cetak kartu nama untuk keperluan personal, usaha, dan organisasi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 22),
('Cetak Name Tag', 'cetak-name-tag', 'Layanan cetak name tag untuk acara, seminar, sekolah, dan kantor.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 23),
('Cetak ID Card', 'cetak-id-card', 'Layanan cetak ID card untuk identitas anggota, karyawan, panitia, dan organisasi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/9b7b584e72e446d59f722b77996d2fdd.jpg', 1, 24),
('Cetak Sertifikat', 'cetak-sertifikat', 'Layanan cetak sertifikat untuk seminar, pelatihan, lomba, dan kegiatan resmi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 25),
('Cetak Lanyard', 'cetak-lanyard', 'Layanan cetak lanyard untuk kartu identitas, panitia, dan kegiatan acara.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/a701343e528b4529980f35bd59f1c312.jpg', 1, 26),
('Cetak Undangan', 'cetak-undangan', 'Layanan cetak undangan sederhana untuk acara, rapat, dan kegiatan internal.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/1eb92f1117f842e4b115ebd3e3725716.jpg', 1, 27),
('Cetak Formulir', 'cetak-formulir', 'Layanan cetak formulir administrasi, sekolah, dan organisasi.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/d2f00ca2278b478f8972ec741afa5327.jpg', 1, 28),
('Penyedia Alat Tulis Kantor', 'penyedia-alat-tulis-kantor', 'Menyediakan berbagai ATK seperti kertas HVS A4/F4, map, amplop, snelhecter, dan perlengkapan administrasi lainnya.', 'https://public.youware.com/users-website-assets/prod/9807b15c-f88c-4ee9-a2d5-04d7d8001cdf/a701343e528b4529980f35bd59f1c312.jpg', 1, 29);
